"use client";

import * as React from "react";

export type { ChartReactionOptions } from "@/components/ui/chart-reactions";

export type CryptoTick = { t: number; price: number; volume: number };

export function mulberry32(seed: number) {
  let state = seed >>> 0;
  return () => {
    state |= 0;
    state = (state + 0x6d2b79f5) | 0;
    let word = Math.imul(state ^ (state >>> 15), 1 | state);
    word = (word + Math.imul(word ^ (word >>> 7), 61 | word)) ^ word;
    return ((word ^ (word >>> 14)) >>> 0) / 4294967296;
  };
}

export function genTicks(seed: number, points: number, start: number, drift: number, vol: number, stepMs = 60000): CryptoTick[] {
  const rand = mulberry32(seed);
  const now = Math.floor(Date.now() / 60000) * 60000;
  let price = start;
  return Array.from({ length: points }, (_, index) => {
    price = Math.max(start * 0.2, price * (1 + drift + (rand() - 0.5) * vol));
    return { t: now - (points - 1 - index) * stepMs, price, volume: Math.round(20 + rand() * 180) };
  });
}

export function nextTick(previous: CryptoTick, seedRef: { rand: () => number }, drift: number, vol: number, stepMs = 60000): CryptoTick {
  const price = Math.max(previous.price * 0.2, previous.price * (1 + drift + (seedRef.rand() - 0.5) * vol));
  return { t: previous.t + stepMs, price, volume: Math.round(20 + seedRef.rand() * 180) };
}

export function movingAverage(values: number[], window: number): (number | null)[] {
  return values.map((_, index) => {
    if (index < window - 1) return null;
    let sum = 0;
    for (let offset = 0; offset < window; offset++) sum += values[index - offset]!;
    return sum / window;
  });
}

export function formatPrice(value: number) {
  const digits = value >= 1000 ? 2 : value >= 10 ? 2 : 4;
  return value.toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

export function formatCompactUsd(value: number) {
  if (Math.abs(value) >= 1_000_000_000) return `$${(value / 1_000_000_000).toFixed(2)}B`;
  if (Math.abs(value) >= 1_000_000) return `$${(value / 1_000_000).toFixed(2)}M`;
  if (Math.abs(value) >= 1_000) return `$${(value / 1_000).toFixed(2)}K`;
  return `$${value.toFixed(2)}`;
}

export function useLiveTicks({
  seed = 7,
  points = 120,
  start = 100,
  drift = 0.0004,
  vol = 0.006,
  intervalMs = 1200,
  live = true,
}: {
  seed?: number;
  points?: number;
  start?: number;
  drift?: number;
  vol?: number;
  intervalMs?: number;
  live?: boolean;
} = {}) {
  const randRef = React.useRef<() => number>(mulberry32(seed ^ 0x9e3779b9));
  const [ticks, setTicks] = React.useState<CryptoTick[]>(() => genTicks(seed, points, start, drift, vol));
  const [streaming, setStreaming] = React.useState(live);

  React.useEffect(() => {
    setTicks(genTicks(seed, points, start, drift, vol));
    randRef.current = mulberry32(seed ^ 0x9e3779b9);
  }, [seed, points, start, drift, vol]);

  React.useEffect(() => {
    if (!live || !streaming) return;
    if (typeof document !== "undefined" && document.hidden) return;
    const id = window.setInterval(() => {
      setTicks((current) => {
        if (!current.length) return current;
        const next = nextTick(current[current.length - 1]!, { rand: randRef.current }, drift, vol);
        return [...current.slice(-points + 1), next];
      });
    }, intervalMs);
    return () => window.clearInterval(id);
  }, [live, streaming, intervalMs, points, drift, vol]);

  const last = ticks[ticks.length - 1];
  const first = ticks[0];
  const change = last && first ? (last.price / first.price - 1) * 100 : 0;
  return { ticks, last, change, streaming, setStreaming };
}

"use client";

import * as React from "react";

import { Card } from "@/components/ui/card";
import { ChartSkeleton } from "@/components/ui/chart-reactions";
import { formatPrice, mulberry32, type ChartReactionOptions } from "@/components/ui/crypto-feed";
import { cn } from "@/lib/utils";

export type TradePrint = { id: number; t: number; price: number; amount: number; side: "buy" | "sell" };

function nextPrint(id: number, previous: number, rand: () => number): TradePrint {
  const side = rand() > 0.48 ? "buy" : "sell";
  const drift = (rand() - 0.5) * previous * 0.0012;
  return {
    id,
    t: Date.now(),
    price: Math.max(previous * 0.5, previous + drift),
    amount: 0.001 + rand() * rand() * 3.5,
    side,
  };
}

export function TradesFeed({
  symbol = "BTC/USDT",
  basePrice = 97500,
  seed = 41,
  tickMs = 900,
  rows = 16,
  className,
  isLoading,
  reaction,
}: {
  symbol?: string;
  basePrice?: number;
  seed?: number;
  tickMs?: number;
  rows?: number;
  className?: string;
  isLoading?: boolean;
  reaction?: ChartReactionOptions;
}) {
  const randRef = React.useRef<() => number>(mulberry32(seed));
  const idRef = React.useRef(1);
  const [prints, setPrints] = React.useState<TradePrint[]>([]);

  React.useEffect(() => {
    randRef.current = mulberry32(seed);
    idRef.current = 1;
    const out: TradePrint[] = [];
    let price = basePrice;
    const now = Date.now();
    for (let index = 0; index < rows; index++) {
      const print = nextPrint(idRef.current++, price, randRef.current);
      print.t = now - (rows - index) * tickMs;
      price = print.price;
      out.push(print);
    }
    setPrints([...out].reverse());
    const id = window.setInterval(() => {
      if (document.hidden) return;
      setPrints((current) => {
        const currentPrice = current[0]?.price ?? basePrice;
        return [nextPrint(idRef.current++, currentPrice, randRef.current), ...current].slice(0, rows);
      });
    }, tickMs);
    return () => window.clearInterval(id);
  }, [seed, tickMs, rows, basePrice]);

  void reaction;

  return (
    <Card className={cn("min-w-0 w-full p-5", className)} role="region" aria-label={`${symbol} latest trades`}>
      <ChartSkeleton isLoading={isLoading}>
        <style>{`@keyframes trade-in { from { background-color: var(--accent); } to { background-color: transparent; } }`}</style>
        <div className="flex items-center justify-between gap-2">
          <p className="truncate text-[15px] font-medium tracking-tight">Latest trades</p>
          <p className="font-mono text-[11px] text-muted-foreground">{symbol}</p>
        </div>
        <div className="mt-2 grid grid-cols-[1fr_1fr_1fr] px-1 font-mono text-[10px] uppercase tracking-wide text-muted-foreground" aria-hidden>
          <span>Price</span><span className="text-right">Amount</span><span className="text-right">Time</span>
        </div>
        <ul className="mt-1 space-y-[1px]" aria-live="off" aria-label="Recent prints">
          {prints.map((print, index) => (
            <li
              key={print.id}
              style={index === 0 ? { animation: "trade-in 900ms ease-out" } : undefined}
              className="grid grid-cols-[1fr_1fr_1fr] rounded px-1 py-[3px] font-mono text-[11px] tabular-nums"
            >
              <span className={print.side === "buy" ? "text-chart-up" : "text-destructive"}>${formatPrice(print.price)}</span>
              <span className="text-right text-foreground">{print.amount.toFixed(4)}</span>
              <span className="text-right text-muted-foreground">{new Date(print.t).toLocaleTimeString("en-US", { hour12: false })}</span>
            </li>
          ))}
        </ul>
      </ChartSkeleton>
    </Card>
  );
}
